'use strict';
(()=>{const A=RepoAccount,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let busy=false,timer,items=[],cursor=null,sessionUser=null,canCancel=false,publication={},lastLoaded=0;
const when=value=>{const date=new Date(value);return Number.isFinite(date.getTime())?date.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):null};
const reason=value=>({catalogue_moderation:'This repository does not currently meet RepoShelf’s catalogue policy.',no_demo:'No public demo link was found. Add one to the repository homepage or README, then submit again.',repository_unavailable:'The repository is unavailable or excluded from the catalogue.',rate_limit:'GitHub temporarily limited this check.',temporary_error:'A temporary error interrupted this scan.',screenshot_error:'The demo loaded, but its preview could not be captured.',unsafe_target:'The demo address could not be safely opened.',empty_page:'The demo did not render enough content to validate.'}[value]||'The demo or its screenshot could not be confirmed.');
function render(){const labels={queued:'Queued for scan',processing:'Scanning repository',imported:'Imported into saved catalogue',retry:'Waiting for an automatic retry',unavailable:'Not accepted',cancelled:'Cancelled'};$('#submission-list').innerHTML=items.length?items.map(r=>{const details=r.result_details||{},accepted=r.status==='imported'&&details.status==='accepted',published=accepted&&Date.parse(publication.lastPublishedAt)>=Date.parse(r.checked_at);let text='';if(accepted)text=published?'<p>A catalogue publication has completed since this scan. Open the listing to check its current availability.</p>':`<p>Your repository, demo and screenshot passed the catalogue checks. It will be included in the next publication, currently scheduled for <strong>${esc(when(publication.nextScheduledAt)||'06:35 UTC daily')}</strong>. An administrator may publish sooner; scheduled runs can be delayed.</p>`;else if(r.status==='imported')text=r.with_demo?'<p>A demo link was found by this earlier scan. Open the listing to check its current availability.</p>':'<p>This earlier submission has no demo link. Add a demo link to its README or homepage before submitting again.</p>';else if(r.status==='retry')text=`<p>${esc(reason(details.reason))} Your request is saved for another check${r.next_attempt_at?' from '+esc(when(r.next_attempt_at)):''}.</p>`;else if(r.status==='unavailable')text=`<p>${esc(reason(details.reason||'no_demo'))}</p>`;else if(r.status==='processing')text='<p>The scan has started. Cancellation is no longer available.</p>';else if(r.status==='queued')text='<p>A dedicated scan has been requested. GitHub queues and an active catalogue sync can delay its start.</p>';else if(r.status==='cancelled')text='<p>This request was cancelled before scanning. Catalogue entries are managed separately from submission requests.</p>';return `<article class="promotion-record"><span class="promotion-status">${esc(accepted?(published?'Accepted':'Accepted · awaiting publication'):labels[r.status]||r.status)}</span><h3>${esc(r.canonical_name||r.repo_name)}</h3>${text}${r.status==='imported'&&r.with_demo?`<a class="button outline" href="/?project=${encodeURIComponent(r.canonical_name||r.repo_name)}">View listing</a>`:''}${canCancel&&['queued','retry'].includes(r.status)?`<button class="button outline" data-cancel-submission="${esc(r.id)}" aria-label="Cancel submission for ${esc(r.repo_name)}">Cancel submission</button>`:''}<p class="submission-time">Submitted ${esc(when(r.created_at))}${r.checked_at?' · Checked '+esc(when(r.checked_at)):''} · ${Number(r.attempts)||0} scan attempts</p></article>`}).join(''):'<p class="loading-note">Your submitted repositories will appear here.</p>'}
async function load(){const user=A.user?.id,data=await A.request('/api/submissions');if(!user||A.user?.id!==user)return;items=data.items;cursor=data.nextCursor;canCancel=data.canCancel===true;publication=data.publication||{};lastLoaded=Date.now();render();$('#more-submissions').hidden=cursor==null;$('#submission-request button').disabled=!data.workerConfigured;if(!data.workerConfigured)$('#submission-message').textContent='Repository submission is awaiting setup. Existing requests remain saved.';return data}
async function task(fn){if(busy)return;busy=true;$('#refresh-submissions').disabled=true;$('#submission-request button').disabled=true;$('#submission-list').querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn()}catch(e){$('#submission-message').textContent=e.message}finally{busy=false;$('#refresh-submissions').disabled=false;try{await load()}catch{}}}
$('#submission-list').onclick=e=>{const button=e.target.closest('[data-cancel-submission]');if(!button||busy)return;const id=button.dataset.cancelSubmission;if(!confirm('Cancel this queued submission? This stops the request, while catalogue entries are managed separately.'))return;void task(async()=>{await A.request('/api/submissions?action=cancel',{method:'POST',body:JSON.stringify({id})});$('#submission-message').textContent='Submission cancelled.'})};
$('#submission-request').onsubmit=e=>{e.preventDefault();void task(async()=>{const result=await A.request('/api/submissions',{method:'POST',body:JSON.stringify({repository:$('#submission-repo').value})});$('#submission-repo').value='';$('#submission-message').textContent=!result.queued?'This repository is already in your submissions. Its current status is shown below.':result.scanRequested?'Submission saved. A dedicated demo check and screenshot scan has been requested.':'Submission saved. The next available submission scan will check it.'})};$('#refresh-submissions').onclick=()=>void task(load);$('#more-submissions').onclick=async()=>{if(busy||cursor==null)return;busy=true;$('#more-submissions').disabled=true;try{const data=await A.request('/api/submissions?cursor='+cursor);if(A.user?.id!==sessionUser)return;items.push(...data.items);cursor=data.nextCursor;render();$('#more-submissions').hidden=cursor==null}catch(e){$('#submission-message').textContent=e.message}finally{busy=false;$('#more-submissions').disabled=false}};
(async()=>{while(!A.ready)await new Promise(r=>setTimeout(r,50));if(!A.user?.githubConnected){$('#submission-gate').innerHTML=A.user?'<p>Connect your GitHub account to submit a repository and track its progress. Your likes and collection stay with this account.</p><a class="button lime" href="/api/auth?action=link-github&return=%2Fsubmissions.html">Connect GitHub ↗</a>':'<p>Sign in with GitHub to submit a repository and track its progress.</p><a class="button lime" href="/api/auth?action=start&return=%2Fsubmissions.html">Sign in with GitHub ↗</a><p class="small">By signing in you agree to our <a href="/terms.html">Terms of Service</a> and acknowledge our <a href="/privacy.html">Privacy Policy</a>.</p>';return}sessionUser=A.user.id;$('#submission-gate').hidden=true;$('#submission-workspace').hidden=false;try{await load();timer=setInterval(()=>{const active=items.some(r=>['queued','processing'].includes(r.status));if(!document.hidden&&!busy&&items.length<=50&&Date.now()-lastLoaded>=(active?30000:300000))void load().catch(()=>{})},30000)}catch(e){$('#submission-request button').disabled=true;$('#submission-message').textContent=e.message}})();window.addEventListener('pagehide',()=>clearInterval(timer));window.addEventListener('reposhelf-account',()=>{if(sessionUser&&A.ready&&A.user?.id!==sessionUser){clearInterval(timer);location.href='/submissions.html'}});
})();
